import{z as o,x as d,o as A,c as B,q as s,j as r,D as e,d as t,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"事件响应","description":"","frontmatter":{"title":"事件响应","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/incident-response.md","filePath":"cs/incident-response.md","lastUpdated":1791063341000}'),p={name:"cs/incident-response.md"};function m(D,a,T,h,F,c){const n=d("Mermaid");return A(),B("div",null,[a[2]||(a[2]=s('<h1 id="事件响应" tabindex="-1">事件响应 <a class="header-anchor" href="#事件响应" aria-label="Permalink to &quot;事件响应&quot;">​</a></h1><div class="epigraph"><p>事件响应是预先写好的状态机：准备、检测、遏制、根除、恢复、复盘。临时发挥会破坏证据并扩大范围。目标是把事故从灾难收成可管理的窗口。</p><footer>—— NIST SP 800-61；对照 Anderson 对事故</footer></div><p>上一课<a href="/cs/siem-logging">SIEM</a>把日志变成告警，告警之后谁接手、按什么次序做，SIEM 不回答。缺口是<strong>人与流程接到告警之后</strong>。本课讲生命周期与证据保全，不写攻击者手册。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>告警不等于已定性：可能是扫描误报，也可能是横向移动的末端，答案只能从证据里来。先隔离再取证，还是先取证再隔离，取决于传播速度：勒索式加密每分钟扩大损失，隔离优先；内存里的密钥一断电就消失，取证优先。权衡不能临场吵，缺口是预先写好的角色分工、沟通渠道与法律保留——哪些证据按呈堂标准链式保管，对外的话由谁说。</p><h3 id="遏制不等于关机" tabindex="-1">遏制不等于关机 <a class="header-anchor" href="#遏制不等于关机" aria-label="Permalink to &quot;遏制不等于关机&quot;">​</a></h3><p>最直觉的遏制是拔电源，但关机丢掉全部易失证据：内存中的密钥、进程列表、连接表随断电蒸发。更准的是网卡隔离——主机继续运行只是断网，传播停了，证据还在；轮换凭证让攻击者的会话立即失效，常比重装机快。</p><p><span class="marginnote">「易失证据」就是一断电就消失的数据：内存里的密钥、当前登录会话、进程列表。可以把它想象成写在你手心的电话号码——洗一次手（关机）就永远找不回来，除非先抄到纸上（转存到取证盘）。</span></p><p><span class="marginnote">SP 800-61。禁止报复性黑客：反击违法，还会毁掉自己的证据。ATT&amp;CK 下一课给对手行为共同语言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>六阶段各答一问：准备写预案、定角色，临场只剩执行；检测把告警定性成事件；遏制止血；根除移除持久化——攻击者几乎总会留后门，只堵入口等于请他回来；恢复分批回归、加严监控；复盘改基线，把暴露的缺口变成新规则。桌面推演在纸上走一遍，先暴露角色空白与联系方式失效这类便宜就能修的错。下一课 ATT&amp;CK 矩阵作检测覆盖图。</p>',12)),(A(),r(l,null,{default:e(()=>[i(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREP%5B%22%E5%87%86%E5%A4%87%22%5D%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20CON%5B%22%E9%81%8F%E5%88%B6%22%5D%0A%20%20CON%20--%3E%20ERAD%5B%22%E6%A0%B9%E9%99%A4%E4%B8%8E%E6%81%A2%E5%A4%8D%22%5D%0A%20%20ERAD%20--%3E%20LES%5B%22%E5%A4%8D%E7%9B%98%E6%94%B9%E5%9F%BA%E7%BA%BF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"响应把纵深从技术接到组织：每层控制都会失效，失效后的秩序由本课提供。生命周期是状态机——每阶段有进入条件、输出物和负责人，跳阶段就是漏洞：没定性就遏制，不知道隔离哪几台；没复盘就恢复，同一扇门下周再开。ATT&CK 下一课把对手技术分类，便于问「我们能看见哪一步」。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"「状态机」就是把流程写成一张表：在什么状态、收到什么输入、转到下一个什么状态。好处是临场不靠争论——查表就知道现在该谁做什么。初学者容易以为响应是按时间线性推进，实际上检测阶段发现问题反弹回遏制是常态。")],-1)),a[6]||(a[6]=E("p",null,"接到告警后的第一道分叉是隔离与取证的先后，它由传播速度决定：",-1)),(A(),r(l,null,{default:e(()=>[i(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%91%8A%E8%AD%A6%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20Q%7B%22%E4%BC%A0%E6%92%AD%E9%80%9F%E5%BA%A6%E6%9C%89%E5%A4%9A%E5%BF%AB%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E6%AF%8F%E5%88%86%E9%92%9F%E5%9C%A8%E6%89%A9%E5%A4%A7%E6%8D%9F%E5%A4%B1%EF%BC%88%E5%A6%82%E5%8B%92%E7%B4%A2%E5%8A%A0%E5%AF%86%EF%BC%89%22%20--%3E%20ISO%5B%22%E5%85%88%E9%9A%94%E7%A6%BB%EF%BC%9A%E7%BD%91%E5%8D%A1%E6%96%AD%E7%BD%91%22%5D%0A%20%20Q%20--%20%22%E4%BC%A0%E6%92%AD%E5%B7%B2%E5%81%9C%EF%BC%8C%E5%85%B3%E9%94%AE%E8%AF%81%E6%8D%AE%E5%8F%AA%E5%9C%A8%E5%86%85%E5%AD%98%22%20--%3E%20FOR%5B%22%E5%85%88%E5%8F%96%E8%AF%81%EF%BC%9A%E6%8A%93%E5%86%85%E5%AD%98%E4%B8%8E%E8%BF%9E%E6%8E%A5%E8%A1%A8%22%5D%0A%20%20ISO%20--%3E%20FOR2%5B%22%E4%BA%8B%E5%90%8E%E8%A1%A5%E5%8F%96%E8%AF%81%22%5D%0A%20%20FOR2%20--%3E%20E%5B%22%E8%BF%9B%E5%85%A5%E6%A0%B9%E9%99%A4%E9%98%B6%E6%AE%B5%22%5D%0A%20%20FOR%20--%3E%20E%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写攻击复现：对手视角只要求「行为有名字」，条目归下一课 ATT&amp;CK。遏制时限由业务定；复盘文档常按法律特权保管，公开范围先过法务。</p><p><span class="marginnote">「链式保管」指证据从取得那一刻起，每次转手都有签字记录，证明它没被人动过。法庭先不问「证据说明了什么」，先问「你怎么证明它还是原来的样子」——记录断一处，整条证据链就可能作废。这就是为什么取证操作要在只读镜像上做。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>日志之后要状态机，不要临时发挥。</li><li>遏制与取证权衡要预先写。</li><li>复盘必须改基线，否则只演戏。</li><li>下一课 ATT&amp;CK。</li><li>出处：NIST SP 800-61；Anderson。</li></ul>',5))])}const f=o(p,[["render",m]]);export{C as __pageData,f as default};
